-- 0027: 붙임5 추진계획 서술 플레이스홀더 연결 + 붙임6·9·10·11·12 확약문/서명 표 테두리 통합·붙임태그.
--  (붙임10 관리책임자/연락처 주석 원문 복원 포함)

update public.document_templates set name='경영개선지원 신청서', attachment_no='붙임5', html_content=$html$<!doctype html><html lang="ko"><head><meta charset="utf-8"><style> @page{size:A4;margin:14mm 14mm} body{color:#000;font-size:10pt;line-height:1.4} .tag{display:inline-block;border:1px solid #000;background:#f2f2f2;font-weight:700;font-size:11pt;padding:2pt 10pt;margin:0 0 4pt} h1{text-align:center;font-size:18pt;font-weight:800;letter-spacing:0.5px;margin:0 0 10pt} .sec{font-weight:800;font-size:12pt;margin:10pt 0 3pt} table{border-collapse:collapse;width:100%;table-layout:fixed;margin:2pt 0} th,td{border:1px solid #000;padding:3.5pt 5pt;vertical-align:middle} th{background:#f2f2f2;font-weight:700;text-align:center;font-size:10pt} td{text-align:left;font-size:10pt} .sub{font-weight:400;font-size:8.5pt}.rt{text-align:right}.chk{letter-spacing:0.3px} .box{height:34pt;vertical-align:top} .photo{height:118pt;text-align:center;color:#8a8a8a;font-size:9pt;vertical-align:middle} .note{font-size:9pt;color:#333;margin:2pt 1px} .stmtcell{text-align:justify;line-height:1.5;padding:6pt} .sigwho{text-align:left}.sigmark{text-align:center;width:18%} .foot-in{font-weight:800;font-size:11pt} </style></head><body><span class="tag">붙임 5</span><h1>대전 소상공인·자영업자 재기지원사업 경영개선지원 신청서</h1><p class="sec">1. 지원업체 현황</p><table><colgroup><col style="width:19%"><col style="width:31%"><col style="width:19%"><col style="width:31%"></colgroup><tr><th>상 호 명</th><td>{{business_name}}</td><th>사업자등록번호<br><span class="sub">(법인등록번호)</span></th><td>{{business_reg_no}}</td></tr><tr><th>대표자</th><td>{{owner_name}}</td><th>연락처</th><td>{{phone}}</td></tr><tr><th>사업장 주소</th><td colspan="3">{{address}}</td></tr><tr><th>상시근로자<br><span class="sub">(대표자 제외)</span></th><td class="rt">{{employee_count}} 명</td><th>개업연월일</th><td>{{opened_at}}</td></tr><tr><th>업 태</th><td>{{business_type}}</td><th>종 목</th><td>{{item}}</td></tr></table><p class="sec">2. 컨설팅</p><table><colgroup><col style="width:19%"><col style="width:31%"><col style="width:19%"><col style="width:31%"></colgroup><tr><th>성 명<br><span class="sub">(컨설턴트)</span></th><td>{{consultant_name}}</td><th>연락처<br><span class="sub">(컨설턴트)</span></th><td>{{consultant_phone}}</td></tr><tr><th>컨설팅일자</th><td colspan="3">(1차) {{consulting_date_1}} &nbsp;&nbsp; (2차) {{consulting_date_2}} &nbsp;&nbsp; (3차) {{consulting_date_3}}</td></tr></table><p class="sec">3. 경영개선자금 신청내역</p><table><colgroup><col style="width:19%"><col style="width:31%"><col style="width:19%"><col style="width:31%"></colgroup><tr><th>총 신청내역</th><td class="chk" colspan="3">{{cat_hygiene}} 위생관리 &nbsp; {{cat_safety}} 안전관리 &nbsp; {{cat_promo}} 홍보(광고) &nbsp; {{cat_env}} 환경개선 &nbsp; {{cat_pos}} POS경비</td></tr><tr><th>총소요비용</th><td colspan="3">※ 지원금 최대 300만원 (부가가치세는 자부담)</td></tr><tr><th>소요금액<br><span class="sub">(부가세 제외)</span></th><td class="rt">{{cost_excl_vat}} 원</td><th>지원금신청액<br><span class="sub">(소요금액의 100%)</span></th><td class="rt">{{requested_amount}} 원</td></tr><tr><th>시공(제작)내용</th><td colspan="3">{{reason}}</td></tr><tr><th>단위사업</th><td></td><th>소요금액 <span class="sub">(부가세 제외)</span></th><td class="rt">원</td></tr><tr><th>단위사업</th><td></td><th>소요금액 <span class="sub">(부가세 제외)</span></th><td class="rt">원</td></tr><tr><th>단위사업</th><td></td><th>소요금액 <span class="sub">(부가세 제외)</span></th><td class="rt">원</td></tr></table><p class="note">* 필요시 칸 추가 기재</p><p class="sec">4. 시공(제작) 내용 <span class="sub">(외주업체별로 작성 · 필요시 페이지 추가)</span></p><table><colgroup><col style="width:19%"><col style="width:31%"><col style="width:19%"><col style="width:31%"></colgroup><tr><th>단위사업</th><td class="chk" colspan="3">□ 위생관리 &nbsp; □ 안전관리 &nbsp; □ 홍보(광고) &nbsp; □ 환경개선 &nbsp; □ POS경비</td></tr><tr><th>외주 업체명<br><span class="sub">(업체 지역)</span></th><td>{{contractor_name}}</td><th>사업자등록번호</th><td>{{contractor_reg_no}}</td></tr><tr><th>대표자명</th><td>{{contractor_rep}}</td><th>업태/종목</th><td>{{contractor_work_type}}</td></tr><tr><th>사업장 연락처</th><td>{{contractor_phone}}</td><th>휴대전화</th><td></td></tr><tr><th>시공기간</th><td colspan="3">　　월　　일　~　　월　　일</td></tr><tr><th>시공내용</th><td colspan="3">{{contractor_work_type}}</td></tr></table><table style="margin-top:4pt"><colgroup><col style="width:19%"><col style="width:31%"><col style="width:19%"><col style="width:31%"></colgroup><tr><th>단위사업</th><td class="chk" colspan="3">□ 위생관리 &nbsp; □ 안전관리 &nbsp; □ 홍보(광고) &nbsp; □ 환경개선 &nbsp; □ POS경비</td></tr><tr><th>외주 업체명<br><span class="sub">(업체 지역)</span></th><td></td><th>사업자등록번호</th><td></td></tr><tr><th>대표자명</th><td></td><th>업태/종목</th><td></td></tr><tr><th>사업장 연락처</th><td></td><th>휴대전화</th><td></td></tr><tr><th>시공기간</th><td colspan="3">　　월　　일　~　　월　　일</td></tr><tr><th>시공내용</th><td colspan="3"></td></tr></table><table style="margin-top:4pt"><colgroup><col style="width:19%"><col style="width:31%"><col style="width:19%"><col style="width:31%"></colgroup><tr><th>단위사업</th><td class="chk" colspan="3">□ 위생관리 &nbsp; □ 안전관리 &nbsp; □ 홍보(광고) &nbsp; □ 환경개선 &nbsp; □ POS경비</td></tr><tr><th>외주 업체명<br><span class="sub">(업체 지역)</span></th><td></td><th>사업자등록번호</th><td></td></tr><tr><th>대표자명</th><td></td><th>업태/종목</th><td></td></tr><tr><th>사업장 연락처</th><td></td><th>휴대전화</th><td></td></tr><tr><th>시공기간</th><td colspan="3">　　월　　일　~　　월　　일</td></tr><tr><th>시공내용</th><td colspan="3"></td></tr></table><p class="sec">5. 추진계획</p><table><colgroup><col style="width:19%"><col style="width:81%"></colgroup><tr><th>구 분</th><th>주 요 내 용</th></tr><tr><th>사업소개</th><td class="box">{{plan_intro}}</td></tr><tr><th>경영상황</th><td class="box">{{plan_status}}</td></tr><tr><th>지원 필요성</th><td class="box">{{plan_need}}</td></tr><tr><th>기대효과</th><td class="box">{{plan_effect}}</td></tr></table><p class="sec">6. 사업장 사진</p><p class="note">* 현재 사업장 내·외부 사진(간판이 보이게 촬영), 시공할 장소 사진</p><table><colgroup><col style="width:50%"><col style="width:50%"></colgroup><tr><td class="photo">(사업장 사진 첨부)</td><td class="photo">(사업장 사진 첨부)</td></tr><tr><td class="photo">(사업장 사진 첨부)</td><td class="photo">(사업장 사진 첨부)</td></tr><tr><td class="photo">(사업장 사진 첨부)</td><td class="photo">(사업장 사진 첨부)</td></tr></table><table style="margin-top:8pt"><colgroup><col style="width:41%"><col style="width:41%"><col style="width:18%"></colgroup><tr><td class="stmtcell" colspan="3"><b>(수혜대상(대표자))</b> ▶ 본 참여 신청서 및 공고문의 내용을 모두 확인하고 본인이 직접 서명함을 확인합니다. ▶ 서류 누락 또는 공고문 내용을 위반하는 경우 지원 탈락으로 간주함에 동의합니다.</td></tr><tr><td style="text-align:center">{{application_date}}</td><td class="sigwho">신청업체(대표자) {{owner_name}}</td><td class="sigmark">{{{sign_applicant}}}</td></tr><tr><td class="foot-in" style="text-align:center">{{institution}} 귀하</td><td class="sigwho">컨설턴트 {{consultant_name}}</td><td class="sigmark">{{{sign_consultant}}}</td></tr><tr><th rowspan="2">첨부서류</th><td colspan="2" style="text-align:left">【필수】 외주업체 사업자등록증 사본 1부, 견적서 1부(100만원 이상일 경우 견적서 2개 이상), 사업참여 및 중복지원 금지 확약서</td></tr><tr><td colspan="2" style="text-align:left">【해당 시】 옥외광고업 등록증</td></tr></table></body></html>$html$ where template_key='support_application_management';

update public.document_templates set name='사업참여 및 중복지원 금지 확약서', html_content=$html$<!doctype html><html lang="ko"><head><meta charset="utf-8"><style>@page{size:A4;margin:16mm 15mm}body{color:#000;font-size:10pt;line-height:1.5}.tag{display:inline-block;border:1px solid #000;background:#f2f2f2;font-weight:700;font-size:11pt;padding:2pt 10pt;margin:0 0 4pt}.top{text-align:center;font-size:11pt;font-weight:700;margin:0}h1{text-align:center;font-size:18pt;font-weight:800;letter-spacing:1px;margin:2pt 0 10pt}.sec{font-weight:800;font-size:12pt;margin:11pt 0 3pt}table{border-collapse:collapse;width:100%;table-layout:fixed;margin:3pt 0}th,td{border:1px solid #000;padding:4pt 6pt;vertical-align:middle}th{background:#f2f2f2;font-weight:700;text-align:center;width:22%;font-size:10pt}td{text-align:left;width:28%;font-size:10pt}.sub{font-weight:400;font-size:8.5pt}.box td{border:1px solid #000}.box .clause{text-align:justify;line-height:1.55;padding:5pt}.box .stmt{text-align:justify;padding:6pt}.box .sign{text-align:center;padding:8pt 6pt}.box .foot{text-align:center;font-weight:800;font-size:11pt;padding:6pt}</style></head><body><span class="tag">붙임 6</span><h1>사업참여 및 중복지원 금지 확약서</h1><table><tr><th>업 체 명</th><td>{{business_name}}</td><th>대표자</th><td>{{owner_name}}</td></tr><tr><th>사업자등록번호</th><td>{{business_reg_no}}</td><th>전화번호</th><td>{{phone}}</td></tr><tr><th>업 태</th><td>{{business_type}}</td><th>종 목</th><td>{{item}}</td></tr><tr><th>사업장 주소</th><td colspan="3">{{address}}</td></tr></table><table class="box"><colgroup><col style="width:100%"></colgroup><tr><td class="clause">1. 본인은 「대전 소상공인·자영업자 재기지원사업」 참여를 위하여 공고문 및 신청서 내용을 확인하였으며, 제반사항을 준수하여 사업을 수행하겠음.<br>2. 본인은 중앙정부 및 대전시·자치구 등 타 지원기관에서 실시하고 있는 경영개선 지원사업(경영환경개선사업)에 동일·유사한 내용으로 중복적인 지원을 받지 않겠음을 확약함.<br>3. 만약, 중복지원을 받는 경우 지원금 환수 조치 등 민·형사상의 책임을 부담할 것을 확인함.<br>4. 본인은 지원금 신청 내용과 증빙자료가 진실하며, 사실과 다르거나, 위법·부당한 방법을 통하여 지원받을 경우 지원액 전액 환수 및 향후 지원사업에서 배제되며, 발생하는 모든 법적 책임을 부담할 것을 확약함.</td></tr><tr><td class="stmt">위와 같이 「대전 소상공인·자영업자 재기지원(컨설팅·경영개선) 사업」에 참여하기 위해 사업 참여 및 중복지원 금지 확약서를 제출합니다.</td></tr><tr><td class="sign">{{today}}<br>(업체명) {{business_name}} &nbsp;&nbsp; (대표자) {{owner_name}} &nbsp; {{{sign_applicant}}}</td></tr><tr><td class="foot">(재)대전일자리경제진흥원장 귀하</td></tr></table></body></html>$html$ where template_key='pledge_no_overlap';

update public.document_templates set name='옥외광고물 표시 신고(허가) 비대상 확인서', html_content=$html$<!doctype html><html lang="ko"><head><meta charset="utf-8"><style>@page{size:A4;margin:16mm 15mm}body{color:#000;font-size:10pt;line-height:1.5}.tag{display:inline-block;border:1px solid #000;background:#f2f2f2;font-weight:700;font-size:11pt;padding:2pt 10pt;margin:0 0 4pt}.top{text-align:center;font-size:11pt;font-weight:700;margin:0}h1{text-align:center;font-size:18pt;font-weight:800;letter-spacing:1px;margin:2pt 0 10pt}.sec{font-weight:800;font-size:12pt;margin:11pt 0 3pt}table{border-collapse:collapse;width:100%;table-layout:fixed;margin:3pt 0}th,td{border:1px solid #000;padding:4pt 6pt;vertical-align:middle}th{background:#f2f2f2;font-weight:700;text-align:center;width:22%;font-size:10pt}td{text-align:left;width:28%;font-size:10pt}.sub{font-weight:400;font-size:8.5pt}.box td{border:1px solid #000}.box .clause{text-align:justify;line-height:1.55;padding:5pt}.box .stmt{text-align:justify;padding:6pt}.box .sign{text-align:center;padding:8pt 6pt}.box .foot{text-align:center;font-weight:800;font-size:11pt;padding:6pt}</style></head><body><span class="tag">붙임 9</span><p class="top">대전 소상공인·자영업자 재기지원사업 경영개선지원</p><h1>옥외광고물 표시 신고(허가) 비대상 확인서</h1><p class="sec">1. 지원업체 현황</p><table><tr><th>상 호 명</th><td>{{business_name}}</td><th>사업자등록번호<br><span class="sub">(법인등록번호)</span></th><td>{{business_reg_no}}</td></tr><tr><th>사업장 주소</th><td colspan="3">{{address}}</td></tr><tr><th>대표자</th><td>{{owner_name}}</td><th>연락처</th><td>{{phone}}</td></tr></table><p class="sec">2. 외주(제작)업체</p><table><tr><th>업 체 명</th><td>{{contractor_name}}</td><th>사업자등록번호<br><span class="sub">(법인등록번호)</span></th><td>{{contractor_reg_no}}</td></tr><tr><th>사업장 주소</th><td colspan="3">{{contractor_address}}</td></tr><tr><th>대표자</th><td>{{contractor_rep}}</td><th>연락처</th><td>{{contractor_phone}}</td></tr><tr><th>옥외광고물 종류</th><td colspan="3">□ 간판 &nbsp;&nbsp; □ LED전광판 &nbsp;&nbsp; □ 기타(　　　　　)</td></tr><tr><th>비대상근거</th><td colspan="3">□ 신고(허가) 대상의 사이즈 및 광고물이 아닐 경우<br>□ 간판 내부의 LED만 교체했을 경우<br>□ 기타(하단 근거 필수기재) (　　　　　　　　　　)</td></tr></table><p class="sub" style="margin:5px 2px">※ 옥외광고물 제작 업체의 옥외광고업 등록증 사본 1부 별도 첨부</p><table class="box"><colgroup><col style="width:100%"></colgroup><tr><td class="stmt">위 사업자의 설치 옥외광고물은 「옥외광고물 등 관리법」 제3조 제1항 및 동법 시행령 제7조 제1항(제9조 제1항)에 따라 신고(허가) 대상이 아님을 확인하며, 무허가 옥외광고물(간판, 전기류 등) 설치로 인한 문제 발생 시 조치할 것을 확약합니다.<br>※ 전기를 이용하는 광고물(네온류, 전광류 등 포함)은 신고(허가)대상이며, 대전광역시 옥외광고물 등의 관리와 옥외광고산업 진흥에 관한 조례를 준수함을 확약합니다.</td></tr><tr><td class="sign">{{today}}<br>신청업체(대표자) {{owner_name}} &nbsp; {{{sign_applicant}}} &nbsp;&nbsp;&nbsp; 외주업체 대표 {{contractor_rep}} &nbsp; {{{sign_contractor}}}</td></tr><tr><td class="foot">대전일자리경제진흥원장 귀하</td></tr></table></body></html>$html$ where template_key='outdoor_ad_exempt';

update public.document_templates set name='영상정보처리기기 운영·관리 방침', html_content=$html$<!doctype html><html lang="ko"><head><meta charset="utf-8"><style>@page{size:A4;margin:16mm 15mm}body{color:#000;font-size:10pt;line-height:1.5}.tag{display:inline-block;border:1px solid #000;background:#f2f2f2;font-weight:700;font-size:11pt;padding:2pt 10pt;margin:0 0 4pt}.top{text-align:center;font-size:11pt;font-weight:700;margin:0}h1{text-align:center;font-size:18pt;font-weight:800;letter-spacing:1px;margin:2pt 0 10pt}.sec{font-weight:800;font-size:12pt;margin:11pt 0 3pt}table{border-collapse:collapse;width:100%;table-layout:fixed;margin:3pt 0}th,td{border:1px solid #000;padding:4pt 6pt;vertical-align:middle}th{background:#f2f2f2;font-weight:700;text-align:center;width:22%;font-size:10pt}td{text-align:left;width:28%;font-size:10pt}.sub{font-weight:400;font-size:8.5pt}.box td{border:1px solid #000}.box .clause{text-align:justify;line-height:1.55;padding:5pt}.box .stmt{text-align:justify;padding:6pt}.box .sign{text-align:center;padding:8pt 6pt}.box .foot{text-align:center;font-weight:800;font-size:11pt;padding:6pt}</style></head><body><span class="tag">붙임 10</span><p class="top">대전 소상공인·자영업자 재기지원사업 경영개선지원</p><h1>영상정보처리기기 운영·관리 방침</h1><p class="sec">1. 지원업체 현황</p><table><tr><th>상 호 명</th><td>{{business_name}}</td><th>사업자등록번호<br><span class="sub">(법인등록번호)</span></th><td>{{business_reg_no}}</td></tr><tr><th>사업장 주소</th><td colspan="3">{{address}}</td></tr><tr><th>대표자</th><td>{{owner_name}}</td><th>연락처</th><td>{{phone}}</td></tr></table><p class="sec">2. 영상정보처리기기 운영·관리 방침</p><table><tr><th>설치목적</th><td colspan="3">□ 시설안전 및 화재 예방 &nbsp;&nbsp; □ 고객 안전 및 범죄 예방</td></tr><tr><th>설치장소</th><td></td><th>설치대수</th><td></td></tr><tr><th>촬영범위</th><td></td><th>촬영시간</th><td></td></tr><tr><th>관리책임자<br><span class="sub">*위탁계약 시 수탁업체 담당자 기재</span></th><td></td><th>연락처<br><span class="sub">*위탁계약 시 수탁업체 담당자 기재</span></th><td></td></tr></table><p class="sub" style="margin:5px 2px">※ CCTV 안내판 필수 설치 및 사진 제출 (기재내용 : 설치 목적·장소·범위, 촬영시간, 책임자 성명·연락처)</p><table class="box"><colgroup><col style="width:100%"></colgroup><tr><td class="stmt">위 사업자는 「개인정보 보호법」 제25조에 따라 영상정보처리기기를 설치·운영하고 있으며, 개인영상정보의 무단 유출 및 공개를 금지(동법 제18조), 개인영상정보에 관하여 열람 또는 존재 확인·삭제를 요구한 경우 필요한 조치를 하겠습니다.(동법 제35조 및 제36조) 또한 기록된 영상정보를 안전하게 관리(동법 제25조 및 제29조), 개인정보 처리 운영방침 수립 및 공개(동법 제30조)를 확약합니다.</td></tr><tr><td class="sign">{{today}}<br>신청업체(대표자) {{owner_name}} &nbsp; {{{sign_applicant}}}</td></tr><tr><td class="foot">대전일자리경제진흥원장 귀하</td></tr></table></body></html>$html$ where template_key='cctv_policy';

update public.document_templates set name='경영개선지원 변경 승인신청서', html_content=$html$<!doctype html><html lang="ko"><head><meta charset="utf-8"><style>@page{size:A4;margin:16mm 15mm}body{color:#000;font-size:10pt;line-height:1.5}.tag{display:inline-block;border:1px solid #000;background:#f2f2f2;font-weight:700;font-size:11pt;padding:2pt 10pt;margin:0 0 4pt}.top{text-align:center;font-size:11pt;font-weight:700;margin:0}h1{text-align:center;font-size:18pt;font-weight:800;letter-spacing:1px;margin:2pt 0 10pt}.sec{font-weight:800;font-size:12pt;margin:11pt 0 3pt}table{border-collapse:collapse;width:100%;table-layout:fixed;margin:3pt 0}th,td{border:1px solid #000;padding:4pt 6pt;vertical-align:middle}th{background:#f2f2f2;font-weight:700;text-align:center;width:22%;font-size:10pt}td{text-align:left;width:28%;font-size:10pt}.sub{font-weight:400;font-size:8.5pt}.box td{border:1px solid #000}.box .clause{text-align:justify;line-height:1.55;padding:5pt}.box .stmt{text-align:justify;padding:6pt}.box .sign{text-align:center;padding:8pt 6pt}.box .foot{text-align:center;font-weight:800;font-size:11pt;padding:6pt}</style></head><body><span class="tag">붙임 11</span><p class="top">대전 소상공인·자영업자 재기지원사업</p><h1>경영개선지원 변경 승인신청서</h1><p class="sec">1. 지원업체 현황</p><table><tr><th>상 호 명</th><td>{{business_name}}</td><th>사업자등록번호<br><span class="sub">(법인등록번호)</span></th><td>{{business_reg_no}}</td></tr><tr><th>사업장 주소</th><td colspan="3">{{address}}</td></tr><tr><th>대표자</th><td>{{owner_name}}</td><th>연락처</th><td>{{phone}}</td></tr></table><p class="sec">2. 변경 승인내용</p><table><tr><th>단위사업</th><td colspan="3">□위생관리 □안전관리 □홍보(광고) □환경개선 □POS경비 □위생방역</td></tr><tr><th>시공(제작)내용</th><td colspan="3">{{contractor_work_type}}</td></tr><tr><th>시공(제작)금액<br><span class="sub">(부가세 제외)</span></th><td>{{contractor_amount}}</td><th>지원금<br><span class="sub">(소요금액 100%)</span></th><td></td></tr><tr><th>변경내용</th><td colspan="3">□ 시공업체 변경 &nbsp; □ 시공금액 변경 &nbsp; □ 시공내용 변경 &nbsp; □ 기타사유(　　)</td></tr><tr><th>변경(전)</th><td></td><th>변경(후)</th><td></td></tr><tr><th>완료예정 일자</th><td colspan="3">　　년　　월　　일</td></tr></table><table class="box"><colgroup><col style="width:100%"></colgroup><tr><td class="stmt">위 본인은 대전일자리경제진흥원에서 추진하는 대전 소상공인·자영업자 재기지원사업의 경영개선지원사업에 선정되었으나, 상기 이유로 인하여 경영개선지원을 변경하기에 신청서를 제출합니다.</td></tr><tr><td class="sign">{{today}}<br>신청업체(대표자) {{owner_name}} &nbsp; {{{sign_applicant}}}</td></tr><tr><td class="foot">대전일자리경제진흥원장 귀하</td></tr></table></body></html>$html$ where template_key='change_request';

update public.document_templates set name='경영개선지원 포기 신청서', html_content=$html$<!doctype html><html lang="ko"><head><meta charset="utf-8"><style>@page{size:A4;margin:16mm 15mm}body{color:#000;font-size:10pt;line-height:1.5}.tag{display:inline-block;border:1px solid #000;background:#f2f2f2;font-weight:700;font-size:11pt;padding:2pt 10pt;margin:0 0 4pt}.top{text-align:center;font-size:11pt;font-weight:700;margin:0}h1{text-align:center;font-size:18pt;font-weight:800;letter-spacing:1px;margin:2pt 0 10pt}.sec{font-weight:800;font-size:12pt;margin:11pt 0 3pt}table{border-collapse:collapse;width:100%;table-layout:fixed;margin:3pt 0}th,td{border:1px solid #000;padding:4pt 6pt;vertical-align:middle}th{background:#f2f2f2;font-weight:700;text-align:center;width:22%;font-size:10pt}td{text-align:left;width:28%;font-size:10pt}.sub{font-weight:400;font-size:8.5pt}.box td{border:1px solid #000}.box .clause{text-align:justify;line-height:1.55;padding:5pt}.box .stmt{text-align:justify;padding:6pt}.box .sign{text-align:center;padding:8pt 6pt}.box .foot{text-align:center;font-weight:800;font-size:11pt;padding:6pt}</style></head><body><span class="tag">붙임 12</span><p class="top">대전 소상공인·자영업자 재기지원사업</p><h1>경영개선지원 포기 신청서</h1><p class="sec">1. 지원업체 현황</p><table><tr><th>상 호 명</th><td>{{business_name}}</td><th>사업자등록번호<br><span class="sub">(법인등록번호)</span></th><td>{{business_reg_no}}</td></tr><tr><th>사업장 주소</th><td colspan="3">{{address}}</td></tr><tr><th>대표자</th><td>{{owner_name}}</td><th>연락처</th><td>{{phone}}</td></tr></table><p class="sec">2. 포기내용</p><table><tr><th>단위사업</th><td colspan="3">□위생관리 □안전관리 □홍보(광고) □환경개선 □POS경비</td></tr><tr><th>시공(제작)내용</th><td colspan="3">{{contractor_work_type}}</td></tr><tr><th>포기사유</th><td colspan="3" style="height:60px;vertical-align:top"></td></tr></table><table class="box"><colgroup><col style="width:100%"></colgroup><tr><td class="stmt">위 본인은 대전일자리경제진흥원에서 추진하는 대전 소상공인·자영업자 재기지원(컨설팅·경영개선) 사업에 선정되었으나, 상기 이유로 인하여 경영개선지원을 포기하기에 신청서를 제출합니다.</td></tr><tr><td class="sign">{{today}}<br>신청업체(대표자) {{owner_name}} &nbsp; {{{sign_applicant}}}</td></tr><tr><td class="foot">대전일자리경제진흥원장 귀하</td></tr></table></body></html>$html$ where template_key='withdrawal_request';

